DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:GTC 017", "old_status": "worked_missing_choice", "status": "ready", "question_id": "b0e8dbc7-e2a5-54cc-b376-cacdc575a9c0", "stem": "Which statement is true?", "choices": [{"key": "A", "text": "The amplitude of f(t)=−2sin(2t)+2 is 1."}, {"key": "B", "text": "The period of g(t)=−(1/2)cos(2t) is π."}, {"key": "C", "text": "The period of h(t)=3tan(2t) is π/4."}, {"key": "D", "text": "The amplitude of k(t)=−3tan(t) is −3."}], "type": "mcq", "correct": "B", "explanation": "The cosine period is 2π/|2|=π. In A the amplitude is 2. In C the tangent period is π/2. Tangent is unbounded and has no amplitude, so D is false.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 64", "note": "Complete original exam page 64 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:GTC 027", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "fae07470-1620-5315-91e4-062864f8847c", "stem": "A linear function f satisfies f(1)=m, f(2)=6, and f(3)=n. What is m+n?", "choices": [], "type": "grid_in", "correct": "12", "explanation": "Equal x-increments give equal changes in f, so 6−m=n−6. Therefore m+n=12.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 87", "note": "Complete original exam page 87 visually checked; answer independently solved and all choices checked. ", "assets": {}, "parts": [{"label": "polynomial", "question_id": "cefadd28-9129-5ede-aaee-18e6653c49e6", "stem": "The polynomial P(x)=(3a−6)x²+(4−2b)x+c−3 is identically zero. What is a+b+c?", "choices": [], "type": "grid_in", "correct": "7", "explanation": "Every coefficient is zero: 3a−6=0, 4−2b=0, c−3=0. Thus a=2, b=2, c=3 and their sum is 7.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Separate complete question recovered from original exam page 87; independently solved.", "assets": {"verification_source": "New exams_251110_.pdf, physical page 87"}}]}, {"id": "clean:GTC 037", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "878740b2-29b1-5ef9-9b7a-4e259a50ec84", "stem": "A rectangle is cut into 20 identical squares, each of area 12.25 cm². Which cannot be the perimeter of the rectangle?", "choices": [{"key": "A", "text": "147 cm"}, {"key": "B", "text": "84 cm"}, {"key": "C", "text": "70 cm"}, {"key": "D", "text": "63 cm"}], "type": "mcq", "correct": "C", "explanation": "Each square has side 3.5 cm. The rectangular arrays have dimensions 1×20, 2×10, or 4×5 squares, with perimeters 7(1+20)=147, 7(2+10)=84, and 7(4+5)=63 cm. Therefore 70 cm is impossible.", "topic": "Coordinate Geometry & Circles", "verification_source": "New exams_251110_.pdf, physical page 119", "note": "Complete original exam page 119 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:HOA 020", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "4dc920df-a133-52a7-b739-377fa240a297", "stem": "Let f(x)=(2−x)(x+4) and g(x)=f(x−10). What is the y-coordinate of the vertex of g?", "choices": [], "type": "grid_in", "correct": "9", "explanation": "Complete the square: f(x)=−x²−2x+8=−(x+1)²+9. A horizontal translation does not change the vertex height, so g has vertex height 9.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 34", "note": "Complete original exam page 34 visually checked; answer independently solved and all choices checked. ", "assets": {}, "parts": [{"label": "positive-solution", "question_id": "a96eff42-8b5f-52f5-8b5d-c793e947a9a9", "stem": "What is the positive solution of x/(x+2)−1/2=x−2?", "choices": [], "type": "grid_in", "correct": "2", "explanation": "For x≠−2, multiplication by 2(x+2) gives 2x−(x+2)=2(x−2)(x+2), hence 2x²−x−6=0=(2x+3)(x−2). The positive solution is 2.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Separate complete question recovered from original exam page 34; independently solved.", "assets": {"verification_source": "New exams_251110_.pdf, physical page 34"}}]}, {"id": "clean:HOA 032", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "fb276b8a-1ff2-5b66-a685-8d2072bae90e", "stem": "Female seasonal-ticket sales were 780 tickets with revenue $47,970 in 2018 and 794 tickets with revenue $47,640 in 2019. With x the number of tickets and y the revenue in dollars, which line fits these two points (intercepts rounded to the nearest tenth)?", "choices": [{"key": "A", "text": "y=−(165/7)x+66355.7"}, {"key": "B", "text": "y=(165/7)x+66355.7"}, {"key": "C", "text": "y=−(165/7)x−66355.7"}, {"key": "D", "text": "y=(165/7)x−66355.7"}], "type": "mcq", "correct": "A", "explanation": "The slope is (47640−47970)/(794−780)=−330/14=−165/7. The intercept is 47970+(165/7)780=66355.714…≈66355.7.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 47", "note": "Complete original exam page 47 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:HOA 042", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "a3b19011-b02e-57fe-b9f6-204954fffbcd", "stem": "Which system of inequalities represents the shaded region in the graph?", "choices": [{"key": "A", "text": "x>0, y>−(2/5)x+2, y<3x+3"}, {"key": "B", "text": "y≥0, y≤−(2/5)x+2, y<3x+3"}, {"key": "C", "text": "y<0, y>−(2/5)x+2, y≥3x+3"}, {"key": "D", "text": "y≥0, y≥−(2/5)x+2, y<3x+3"}], "type": "mcq", "correct": "B", "explanation": "The region is above the solid x-axis, below the solid line y=−(2/5)x+2, and below the dashed line y=3x+3. Solid boundaries are included; the dashed boundary is excluded.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 59", "note": "Complete original exam page 59 visually checked; answer independently solved and all choices checked. ", "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:HOA 071", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "fefe280e-6388-5732-98b7-14158bea04a5", "stem": "The scatterplot compares temperature and relative humidity during one day. What humidity percentage is represented by the data point farthest from the line of best fit?", "choices": [], "type": "grid_in", "correct": "90", "explanation": "Compare the absolute vertical distances from the fitted line. The upper-right point is at 90% humidity, about 7 percentage points above the line, farther than every other point (the next largest distance is about 5).", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 95", "note": "Complete original exam page 95 visually checked; answer independently solved and all choices checked. ", "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:HOA 085", "old_status": "needs_source_reconstruction", "status": "duplicate", "note": "Full original page 110 confirms the cost model C=79+0.44n. With budget 1950, n≤(1950−79)/0.44=4252.2727…, so at most 4252 brochures. This is the existing FA 041 question; linked without adding a duplicate. The adjacent 2000-brochure question is already FA 046 (cost $959).", "correct": "4252", "question_id": "94c44fac-5e46-59d3-a034-8a964f65a31e", "duplicate_of": "topic:FA 041"}, {"id": "clean:HOA 079", "old_status": "worked_missing_choice", "status": "ready", "question_id": "bbc3c0af-fd23-54d4-b1a6-0c92a8a2da07", "stem": "Alonso graphs the ordered pairs (−7,−11), (−4,−5), (−2,−1), (1,5), and (7,17). Which type of function and equation models them?", "choices": [{"key": "A", "text": "Linear: y=2x+3"}, {"key": "B", "text": "Linear: y=−2x+3"}, {"key": "C", "text": "Quadratic: y=x²+4x−32"}, {"key": "D", "text": "Quadratic: y=−2x²−10x+17"}], "type": "mcq", "correct": "A", "explanation": "The change in y is always twice the change in x, so the slope is 2. Substitution of (1,5) gives intercept 3. All five pairs satisfy y=2x+3; each other equation fails at least one pair.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 109", "note": "Complete original exam page 109 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:HOA 091", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "fa628549-be93-53e1-8c10-6de8e9cdc4e6", "stem": "The function h(x)=(x²−a)(4+x)−112 has a zero at x=4. What is a?", "choices": [], "type": "grid_in", "correct": "2", "explanation": "Set h(4)=0: (16−a)·8−112=0. Thus 16−a=14 and a=2.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 116", "note": "Complete original exam page 116 visually checked; answer independently solved and all choices checked. ", "assets": {}, "parts": [{"label": "triangle", "question_id": "371a4073-e675-523e-98e0-7975c2064653", "stem": "In the figure, B, C, and E are collinear, AC=CE, and AC bisects angle BAE. Angle BAC is 20°. What is x, the measure of angle ABE, in degrees?", "choices": [], "type": "grid_in", "correct": "120", "explanation": "Because AC bisects angle BAE, angle CAE=20° and angle BAE=40°. Since AC=CE, triangle ACE has equal base angles CAE and AEC, both 20°. The large triangle ABE therefore gives x=180°−40°−20°=120°.", "topic": "Coordinate Geometry & Circles", "note": "Separate complete question recovered from original exam page 117; independently solved.", "assets": {"verification_source": "New exams_251110_.pdf, physical page 117", "figure": "data:image/jpeg;base64,"}}]}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260929') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260929','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260929'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF q.id IS NOT NULL AND NOT (v ? 'before') THEN RAISE EXCEPTION 'Unexpected existing target %',qid; END IF;
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',coalesce(v->>'verification_source',s.source_document||' page '||s.source_page));
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260929','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260929','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-29. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260929';
